@unittest.skipUnless(importlib.util.find_spec("faster_whisper"), "PyAV decoder requires faster-whisper")
class BrowserAudioDecodeTests(unittest.TestCase):
    def test_opera_webm_opus_reaches_complete_decoder(self):
        samples = decode_voice_audio(_WEBM, "audio/webm")
        self.assertGreater(len(samples), 16000 * 2.8)
        self.assertLess(len(samples), 16000 * 3.2)
        self.assertGreater(float(max(samples)), 0.01)

